export const PB324_MOVES = Object.freeze(RAW_PB324.map((m) => Object.freeze({
  id: m.id,
  index: m.i,
  element: m.el,
  relayElement: m.rel,
  palette: m.pal,
  nameZh: PB324_MOVE_ZH[m.id] ?? m.en,
  nameEn: m.en,
  descZh: PB324_DESC_ZH[m.id] ?? m.en,
  category: m.cat,
  power: m.pwr,
  cooldown: m.cd,
  energy: m.enCost,
  ultimate: m.ult,
  reach: m.reach,
  range: m.rng,
  type: m.type,
  archetype: m.arch,
  windup: m.wu,
  recovery: m.rec,
  multiHit: m.multi,
  motion: Object.freeze({ pose: m.pose ?? "attack", anims: Object.freeze(m.anims ?? []), cues: Object.freeze(m.cues), flags: Object.freeze(m.flags) }),
  vfx: Object.freeze({ fx: m.fx ?? "spark", shapes: Object.freeze(m.shapes), layers: Object.freeze(m.layers), palette: m.pal }),
  hitFeel: Object.freeze({
    hitstop: m.hs,
    shake: m.shk,
    kb: m.kb,
    launch: m.lch,
    punch: m.pnc,
    impact: m.imp,
    stream: m.stm,
    status: m.st
  })
})));

export const PB324_BY_ID = Object.freeze(Object.fromEntries(PB324_MOVES.map((m) => [m.id, m])));

export const PB324_BY_ELEMENT = Object.freeze(Object.fromEntries(PB324_ELEMENTS.map((el) => {
  const all = PB324_MOVES.filter((m) => m.element === el);
  return [el, Object.freeze({
    all: Object.freeze(all),
    skills: Object.freeze(all.filter((m) => !m.ultimate)),
    ultimates: Object.freeze(all.filter((m) => m.ultimate))
  })];
})));

export function isPb324MoveId(id) {
  return typeof id === "string" && Object.prototype.hasOwnProperty.call(PB324_BY_ID, id);
}

export function pb324Move(id) {
  return PB324_BY_ID[id] ?? null;
}

export function pb324CanonicalElement(relayElementOrSpecies = "fire", speciesIndex = 0) {
  const key = String(relayElementOrSpecies ?? "fire").toLowerCase();
  if (key === "storm") return (speciesIndex % 2 === 0) ? "THUNDER" : "WIND";
  if (PB324_ELEMENT_META[key.toUpperCase()]) return key.toUpperCase();
  return RELAY_TO_CANONICAL_10[key] ?? "FIRE";
}

/** Deterministic, diverse 5-skill + 1-ultimate PB-324 kit for any partner species & element.
 *  Slot 0 is ALWAYS a direct offensive projectile/beam/lunge so basic casting immediately lands! */
export function pb324PartnerKit(speciesIndex = 0, relayElement = "fire") {
  const el = pb324CanonicalElement(relayElement, speciesIndex);
  const bucket = PB324_BY_ELEMENT[el] ?? PB324_BY_ELEMENT.FIRE;
  const skills = bucket.skills;
  const ults = bucket.ultimates;
  const picked = [];
  const usedArch = new Set();

  // Slot 0: reliable direct ranged shot (BOLT/SPREAD/LANCE with damage > 0), falling back to any damaging move
  const rangedOffense = skills.filter((m) => m.power > 0 && (m.type === "BOLT" || m.type === "SPREAD" || m.type === "LANCE"));
  const anyOffense = skills.filter((m) => m.power > 0);
  const leadPool = rangedOffense.length ? rangedOffense : anyOffense.length ? anyOffense : skills;
  const lead = leadPool[(speciesIndex * 3) % leadPool.length];
  if (lead) { picked.push(lead.id); usedArch.add(lead.archetype); }

  // Slot 1: distinct direct-cast offensive move (prefer LUNGE/WAVE/BOLT/SPREAD over ZONE so slots 0 & 1 never get blocked by wall-aim)
  const directSecond = anyOffense.filter((m) => !picked.includes(m.id) && m.type !== "ZONE");
  const secondPool = directSecond.length ? directSecond : anyOffense.filter((m) => !picked.includes(m.id));
  if (secondPool.length) {
    const stride1 = (speciesIndex * 5 + 1) % secondPool.length;
    let chosen = null;
    for (let k = 0; k < secondPool.length; k++) {
      const m = secondPool[(stride1 + k) % secondPool.length];
      if (!usedArch.has(m.archetype)) { chosen = m; break; }
    }
    chosen ??= secondPool[stride1];
    picked.push(chosen.id);
    usedArch.add(chosen.archetype);
  }

  // Slots 2..4: diverse remaining skills across archetypes
  const stride = Math.max(1, (speciesIndex * 7 + 3) % Math.max(1, skills.length));
  for (let pass = 0; pass < 2 && picked.length < 5; pass++) {
    for (let k = 0; k < skills.length && picked.length < 5; k++) {
      const m = skills[(stride + k * 3) % skills.length];
      if (picked.includes(m.id)) continue;
      if (pass === 0 && usedArch.has(m.archetype)) continue;
      usedArch.add(m.archetype);
      picked.push(m.id);
    }
  }
  const ult = ults[speciesIndex % Math.max(1, ults.length)]?.id ?? bucket.all[0].id;
  return Object.freeze({
    element: el,
    moves: Object.freeze(picked),
    ultimate: ult,
    pool: Object.freeze(skills.map((m) => m.id))
  });
}

/** Convert a PB-324 record into a simulation-ready relay move definition. */
export function pb324ToRelayMove(id, ultimate = false) {
  const m = PB324_BY_ID[id];
  if (!m) return null;
  const isUlt = Boolean(ultimate || m.ultimate);
  const dmg = isUlt
    ? Math.max(68, Math.min(110, Math.round(52 + m.power * 0.36)))
    : m.power <= 0 ? 0 : Math.max(12, Math.min(44, Math.round(11 + m.power * 0.24)));
  const speed = m.type === "LANCE" ? 1120 : m.type === "BOLT" ? 780 : m.type === "SPREAD" ? 760 : m.type === "WAVE" ? 480 : m.type === "LUNGE" ? 940 : 0;
  const radius = m.type === "NOVA" ? (isUlt ? 245 : 145) : m.type === "ZONE" ? (isUlt ? 145 : 112) : m.type === "WAVE" ? 36 : m.type === "BARRIER" ? 64 : m.type === "LANCE" ? 18 : (isUlt ? 18 : 11); // an ultimate orb hits when its drawn orb touches (2026-11-26)
  const isShot = m.type === "BOLT" || m.type === "SPREAD" || m.type === "LANCE";
  const isArea = m.type === "ZONE" || m.type === "NOVA";
  const onTerrain = isShot ? (m.element === "FIRE" ? "IGNITE" : m.element === "ICE" ? "FREEZE" : undefined) : undefined;
  const freezeWater = isArea && m.element === "ICE" ? true : undefined;
  const onHit = m.hitFeel.status === "burn" ? { burn: 2.5 }
    : m.hitFeel.status === "slow" || m.hitFeel.status === "freeze" ? { slow: 0.45, slowSeconds: 1.6 }
    : m.hitFeel.status === "paralyze" ? { slow: 0.5, slowSeconds: 1.4 }
    : m.hitFeel.status === "poison" ? { burn: 2.2 }
    : (m.element === "FIRE" && isShot ? { burn: 2.5 } : m.element === "ICE" && isShot ? { slow: 0.3, slowSeconds: 1.2 } : undefined);
  const effect = m.hitFeel.status === "freeze" || m.hitFeel.status === "sleep" ? "ROOT"
    : m.hitFeel.status === "burn" ? "IGNITE"
    : m.hitFeel.status === "slow" || m.hitFeel.status === "paralyze" ? "SLOW"
    : (isArea && m.element === "FIRE" ? "IGNITE" : isArea && m.element === "ICE" ? "SLOW" : "NONE");

  return {
    id: m.id,
    type: m.type,
    mechanic: `pb324:${m.element}:${m.archetype}`,
    energy: isUlt ? 80 : m.energy,
    cooldown: isUlt ? 12 : m.cooldown,
    windup: m.windup,
    recovery: m.recovery,
    range: isShot || m.type === "WAVE" ? Math.max(580, Math.round((m.range || 440) * 1.35)) : (m.range || 520),
    distance: m.type === "LUNGE" || m.type === "BLINK" ? Math.max(150, Math.min(320, m.range || 220)) : undefined,
    width: m.type === "LUNGE" ? 72 : undefined,
    speed,
    radius,
    damage: dmg,
    count: m.type === "SPREAD" ? 4 : (m.type === "LANCE" && isUlt ? 3 : 1),
    spread: m.type === "SPREAD" ? 0.65 : (m.type === "LANCE" && isUlt ? 0.35 : 0),
    pierce: m.type === "LANCE" ? (isUlt ? 4 : 2) : (m.archetype === "STREAM_BEAM" ? 2 : 0),
    delay: m.type === "ZONE" ? 0.72 : undefined,
    duration: m.type === "BARRIER" ? 1.4 : undefined,
    arc: m.type === "BARRIER" ? 2.2 : undefined,
    knockback: Math.round(m.hitFeel.kb * 65),
    invulnerable: m.archetype === "SHADOW_BACKSTAB" || m.archetype === "BURROW_AMBUSH" || m.archetype === "MULTI_DASH",
    effect,
    rootSeconds: effect === "ROOT" ? 1.15 : undefined,
    slow: effect === "SLOW" ? 0.45 : undefined,
    slowSeconds: effect === "SLOW" ? 1.6 : undefined,
    ...(onTerrain ? { onTerrain } : {}),
    ...(freezeWater ? { freezeWater } : {}),
    ...(onHit ? { onHit } : {}),
    pb324: m,
    ...(PB_MOVE_TUNING[id] ? { ...PB_MOVE_TUNING[id], stagedTuning: PB_MOVE_TUNING[id] } : {})
  };
}

// PB_MOVE_BY_MOVE_20261127: per-move rule tuning taken from watching each reference move (beat sheets
// are kept outside the repo). A move listed here was staged one at a time:
//   singleDash   strikes once (no follow-up dash of the multi-dash archetype);
//   speed        dash speed in px/s (a "blink" punch crosses the gap in under 0.1 s);
//   windup       seconds the caster stands before moving;
//   lungeKnock   how hard the struck body is pushed (default 340; 0 = pinned in place);
//   reboundSpeed the caster is pushed back off the target after the blow (about speed / 5.5 px);
//   passThrough  the dash carries on through the target and ends on its far side;
//   standOff     how far off the struck body the caster stops, in summed radii (staged default 2.3);
//   type / distance / width  the move's shape, where the game's shape differs from the reference
//                (a punch filed as a zone or a wave becomes the dash it is);
//   comboHits    a blow made of several strikes: [{share, knock?}, {dt, share, knock?}, ...] -- the first
//                lands on contact, each next one `dt` seconds after the one before; shares add up to 1.
export const PB_MOVE_TUNING = Object.freeze({
  'pb-094': Object.freeze({ singleDash: true }),
  'pb-098': Object.freeze({ singleDash: true }),
  'pb-099': Object.freeze({ singleDash: true }),
  'pb-170': Object.freeze({ singleDash: true, speed: 2600, windup: 0.2, lungeKnock: 80, reboundSpeed: 400 }),
  'pb-154': Object.freeze({ singleDash: true, windup: 0.12, lungeKnock: 200, reboundSpeed: 210 }),
  'pb-042': Object.freeze({ singleDash: true, windup: 0.16, speed: 1000, lungeKnock: 70 }),
  'pb-029': Object.freeze({ singleDash: true, windup: 0.25, lungeKnock: 400 }),
  'pb-167': Object.freeze({ singleDash: true, windup: 0.15, speed: 2600, lungeKnock: 20 }),
  'pb-003': Object.freeze({ singleDash: true, windup: 0.17, speed: 1300, lungeKnock: 30, passThrough: true }),
  // Close Combat: steps in, seven jabs 0.15 s apart with the target pinned, gathers 0.3 s, one heavy blow.
  'pb-037': Object.freeze({ windup: 0.15, speed: 1200, standOff: 2.5, comboHits: Object.freeze([{ share: 0.09 }, { dt: 0.15, share: 0.09 }, { dt: 0.15, share: 0.09 },
    { dt: 0.15, share: 0.09 }, { dt: 0.15, share: 0.09 }, { dt: 0.15, share: 0.09 }, { dt: 0.15, share: 0.09 }, { dt: 0.45, share: 0.37, knock: 210 }]) }),
  // High Jump Kick: crouch, straight up three bodies, knee dive, pinned a moment, bounced back two bodies.
  'pb-135': Object.freeze({ singleDash: true, windup: 0.5, speed: 1700, distance: 300, lungeKnock: 0, reboundSpeed: 790 }),
  // Sky Uppercut: low run in, the uppercut carries the target up (drawn), nobody is pushed along the ground.
  'pb-257': Object.freeze({ windup: 0.1, speed: 820, distance: 260, lungeKnock: 0 }),
  // Thunderous Kick: run in, a stomp that pins, then the same leg shoves the target a body away.
  'pb-301': Object.freeze({ singleDash: true, windup: 0.1, speed: 900, comboHits: Object.freeze([{ share: 0.7 }, { dt: 0.3, share: 0.3, knock: 400 }]) }),
  // Dynamic Punch: walks in with the fist charging, one punch, the blast shoves the target a body away.
  'pb-076': Object.freeze({ singleDash: true, windup: 0.12, speed: 380, lungeKnock: 400 }),
  // Focus Punch: 0.7 s of focus, then across the gap in an instant; the target is pinned.
  'pb-109': Object.freeze({ singleDash: true, windup: 0.7, speed: 1700, lungeKnock: 30 }),
  // Drain Punch and Force Palm are dashes in the reference (filed here as a zone and a wave).
  'pb-069': Object.freeze({ type: 'LUNGE', distance: 260, speed: 1100, width: 72, windup: 0.1, lungeKnock: 400 }),
  'pb-111': Object.freeze({ type: 'LUNGE', distance: 290, speed: 2500, width: 72, windup: 0.15, lungeKnock: 400 }),
  // Hammer Arm: grows the arm, walks it in, leans it back and brings it down.
  'pb-126': Object.freeze({ singleDash: true, windup: 0.3, speed: 480, distance: 300, lungeKnock: 200 }),
  // Double Kick: jumps straight up, dives foot first, a second kick from the ground 0.27 s later shoves the target.
  'pb-057': Object.freeze({ windup: 0.35, speed: 900, comboHits: Object.freeze([{ share: 0.5 }, { dt: 0.27, share: 0.5, knock: 400 }]) })
});

export function pb324MoveName(id, locale = "zh-Hant") {
  const m = PB324_BY_ID[id];
  if (!m) return null;
  return locale === "zh-Hant" ? m.nameZh : m.nameEn;
}

export function pb324MoveDesc(id, locale = "zh-Hant") {
  const m = PB324_BY_ID[id];
  if (!m) return null;
  const elMeta = PB324_ELEMENT_META[m.element];
  return locale === "zh-Hant"
    ? `[${elMeta.zh}] ${m.descZh}`
    : `[${elMeta.en}] ${m.nameEn} (${m.archetype})`;
}
